"""Helpers to build journal records for tests."""
import zlib

BEGIN, PATCH, COMMIT, ABORT = 1, 2, 3, 4

def rec(seq, kind, txid, payload=b'', crc=None, plen=None, raw_crc=None, tx_raw=None, seq_raw=None, kind_raw=None):
    if plen is None:
        plen = len(payload)
    head = (int(plen).to_bytes(4, 'little') if plen is not None else b'') \
         + (int(seq).to_bytes(4, 'little') if seq_raw is None else seq_raw) \
         + (bytes([kind]) if kind_raw is None else kind_raw) \
         + (int(txid).to_bytes(4, 'little') if tx_raw is None else tx_raw)
    # if plen was forced, header still uses forced value
    head = int(plen).to_bytes(4, 'little') + (int(seq).to_bytes(4,'little') if seq_raw is None else seq_raw) \
           + (bytes([kind]) if kind_raw is None else kind_raw) + (int(txid).to_bytes(4,'little') if tx_raw is None else tx_raw)
    c = zlib.crc32(head + payload) & 0xffffffff if crc is None else crc
    return head + payload + (c.to_bytes(4, 'little') if raw_crc is None else raw_crc)

def patch(page, off, data):
    return page.to_bytes(2,'little') + off.to_bytes(2,'little') + len(data).to_bytes(2,'little') + data

